package com.gimcompanion;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the GIM Companion site. Requests run on OkHttp's own threads (never the game's),
 * and the answer is handed to a {@link Handler} on that thread.
 */
@Slf4j
@Singleton
public class ApiClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	interface Handler
	{
		/** @param code HTTP status, or -1 if the site couldn't be reached */
		void done(int code, String body);
	}

	@Inject
	private OkHttpClient http;

	@Inject
	private Gson gson;

	void sendBatch(String server, String key, Object batch, Handler handler)
	{
		HttpUrl url = endpoint(server, "events");
		if (url == null)
		{
			handler.done(-1, "Bad server address");
			return;
		}
		RequestBody body = RequestBody.create(JSON, gson.toJson(batch));
		call(new Request.Builder().url(url).header("Authorization", "Bearer " + key).post(body).build(), handler);
	}

	void whoAmI(String server, String key, Handler handler)
	{
		HttpUrl url = endpoint(server, "me");
		if (url == null)
		{
			handler.done(-1, "Bad server address");
			return;
		}
		call(new Request.Builder().url(url).header("Authorization", "Bearer " + key).get().build(), handler);
	}

	/** The "error" message from a JSON error answer, or null. */
	String errorMessage(String body)
	{
		try
		{
			JsonObject json = gson.fromJson(body, JsonObject.class);
			return json != null && json.has("error") ? json.get("error").getAsString() : null;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	private static HttpUrl endpoint(String server, String path)
	{
		HttpUrl base = HttpUrl.parse(server.trim());
		if (base == null)
		{
			return null;
		}
		return base.newBuilder().addPathSegments("api/plugin/" + path).build();
	}

	private void call(Request request, Handler handler)
	{
		http.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("GIM Companion request failed", e);
				handler.done(-1, e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					handler.done(response.code(), body != null ? body.string() : "");
				}
				catch (IOException e)
				{
					handler.done(-1, e.getMessage());
				}
			}
		});
	}
}

package com.gimcompanion;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** One item stack in a drop. {@code value} is the Grand Exchange price of the whole stack. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class DropItem
{
	private int itemId;
	private String name;
	private int qty;
	private long value;
}

package com.gimcompanion;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.function.IntFunction;
import java.util.function.IntToLongFunction;
import net.runelite.client.game.ItemStack;

/** Picks the items worth logging out of a loot drop. No game access, so it's easy to test. */
public final class Drops
{
	private Drops()
	{
	}

	/**
	 * @param priceOf  Grand Exchange price of one of this item (0 if untradeable)
	 * @param nameOf   the item's name
	 * @param minValue log stacks worth at least this much in total
	 */
	public static List<DropItem> worthLogging(Collection<ItemStack> loot, IntToLongFunction priceOf, IntFunction<String> nameOf, long minValue)
	{
		List<DropItem> items = new ArrayList<>();
		for (ItemStack stack : loot)
		{
			long value = priceOf.applyAsLong(stack.getId()) * stack.getQuantity();
			if (value > 0 && value >= minValue && stack.getQuantity() > 0)
			{
				items.add(new DropItem(stack.getId(), nameOf.apply(stack.getId()), stack.getQuantity(), value));
			}
		}
		return items;
	}
}

package com.gimcompanion;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Events waiting to be sent. The plugin saves this list in RuneLite's settings whenever it
 * changes, so events made while the site was unreachable survive a RuneLite restart.
 * Thread-safe: the game thread adds events, the network thread removes sent ones.
 */
public class EventQueue
{
	/** Kept small: if the site is down for a long time, the oldest events are dropped first. */
	static final int MAX_EVENTS = 300;
	/** The site accepts at most this many per request. */
	static final int MAX_PER_BATCH = 200;

	private final List<PluginEvent> events = new ArrayList<>();

	public synchronized void add(PluginEvent event)
	{
		events.add(event);
		while (events.size() > MAX_EVENTS)
		{
			events.remove(0);
		}
	}

	/** The oldest events for this character, up to one batch's worth. */
	public synchronized List<PluginEvent> nextBatch(String rsn)
	{
		return events.stream()
			.filter(e -> rsn.equals(e.getRsn()))
			.limit(MAX_PER_BATCH)
			.collect(Collectors.toList());
	}

	public synchronized boolean hasEventsFor(String rsn)
	{
		return events.stream().anyMatch(e -> rsn.equals(e.getRsn()));
	}

	/** Forgets events the site has confirmed. Returns whether anything changed. */
	public synchronized boolean removeIds(Set<String> ids)
	{
		return events.removeIf(e -> ids.contains(e.getId()));
	}

	public synchronized List<PluginEvent> all()
	{
		return new ArrayList<>(events);
	}

	public synchronized void replaceAll(List<PluginEvent> saved)
	{
		events.clear();
		if (saved != null)
		{
			saved.forEach(this::add);
		}
	}

	public synchronized int size()
	{
		return events.size();
	}
}

package com.gimcompanion;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(GimCompanionConfig.GROUP)
public interface GimCompanionConfig extends Config
{
	String GROUP = "gimcompanion";
	String DEFAULT_SERVER = "https://gim-companion.vercel.app";

	@ConfigSection(
		name = "Advanced",
		description = "Only change these if you run your own copy of the GIM Companion site",
		position = 10,
		closedByDefault = true
	)
	String advanced = "advanced";

	@ConfigItem(
		keyName = "enabled",
		name = "Send data to GIM Companion",
		description = "Send your logins, world, XP and big drops to your group's GIM Companion site",
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers",
		position = 0
	)
	default boolean enabled()
	{
		return false;
	}

	@ConfigItem(
		keyName = "key",
		name = "Key",
		description = "Your personal key from the Group page of the GIM Companion site",
		secret = true,
		position = 1
	)
	default String key()
	{
		return "";
	}

	@Range(min = 0)
	@ConfigItem(
		keyName = "minDropValue",
		name = "Minimum drop value",
		description = "Drops worth at least this many coins (Grand Exchange price) are logged automatically",
		position = 2
	)
	default int minDropValue()
	{
		return 100_000;
	}

	@ConfigItem(
		keyName = "logPets",
		name = "Log pets",
		description = "Log a drop when you get a pet",
		position = 3
	)
	default boolean logPets()
	{
		return true;
	}

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server",
		description = "Address of the GIM Companion site",
		position = 0,
		section = advanced
	)
	default String serverUrl()
	{
		return DEFAULT_SERVER;
	}
}

package com.gimcompanion;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.lang.reflect.Type;
import java.time.temporal.ChronoUnit;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.task.Schedule;
import net.runelite.client.util.Text;

/**
 * Sends your logins, world, XP and big drops to your group's GIM Companion site, which shows
 * who's playing and posts drops to everyone's dashboard. Off until you tick
 * "Send data to GIM Companion" and paste your key from the site's Group page.
 */
@Slf4j
@PluginDescriptor(
	name = "GIM Companion",
	description = "Shares your logins, XP and big drops with your Group Ironman's GIM Companion site",
	tags = {"group", "ironman", "gim", "drops", "tracker"}
)
public class GimCompanionPlugin extends Plugin
{
	private static final String QUEUE_KEY = "pendingEvents";
	private static final Type EVENT_LIST = new TypeToken<List<PluginEvent>>()
	{
	}.getType();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private GimCompanionConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ApiClient api;

	@Inject
	private Gson gson;

	private final EventQueue queue = new EventQueue();
	private final Map<String, Integer> skillXp = new ConcurrentHashMap<>();
	private final AtomicBoolean sending = new AtomicBoolean();

	// Written on the game thread, read on the sending thread.
	private volatile boolean loggedIn;
	private volatile boolean loginPending; // logged in, but the character's name isn't known yet
	private volatile String rsn;
	private volatile int world;
	private volatile boolean xpChanged;

	private volatile long lastSendAt;
	private volatile long lastFailureAt;
	private volatile boolean keyRejected; // stop sending until the settings change
	private volatile boolean announced; // said "connected" in chat this session

	@Override
	protected void startUp()
	{
		loadQueue();
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loggedIn = true;
				loginPending = true;
				world = client.getWorld();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		saveQueue();
		loggedIn = false;
		loginPending = false;
		rsn = null;
		skillXp.clear();
		xpChanged = false;
		keyRejected = false;
		announced = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			world = client.getWorld(); // also catches world hops
			if (!loggedIn)
			{
				loggedIn = true;
				loginPending = true;
			}
		}
		else if (state == GameState.LOGIN_SCREEN && loggedIn)
		{
			loggedIn = false;
			if (rsn != null)
			{
				addEvent(PluginEvent.logout(rsn, System.currentTimeMillis()));
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!loginPending)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null)
		{
			return;
		}
		loginPending = false;
		if (!player.getName().equals(rsn))
		{
			skillXp.clear(); // a different character than last time
		}
		rsn = player.getName();
		announced = false;
		addEvent(PluginEvent.login(rsn, System.currentTimeMillis()));
		readAllSkills();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer before = skillXp.put(SkillNames.of(event.getSkill()), event.getXp());
		if (before == null || before != event.getXp())
		{
			xpChanged = true;
		}
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (!config.enabled() || rsn == null)
		{
			return;
		}
		List<DropItem> items = Drops.worthLogging(
			event.getItems(),
			itemManager::getItemPrice,
			id -> itemManager.getItemComposition(id).getName(),
			config.minDropValue());
		if (!items.isEmpty())
		{
			addEvent(PluginEvent.drop(rsn, System.currentTimeMillis(), event.getName(), items));
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE || !config.enabled() || !config.logPets() || rsn == null)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		if (PetMessages.isPetMessage(message))
		{
			addEvent(PluginEvent.pet(rsn, System.currentTimeMillis(), message));
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!GimCompanionConfig.GROUP.equals(event.getGroup()) || QUEUE_KEY.equals(event.getKey()))
		{
			return;
		}
		keyRejected = false;
		lastFailureAt = 0;
		if (config.enabled() && !config.key().trim().isEmpty())
		{
			checkKey();
		}
	}

	/** Every few seconds, off the game thread: send a batch if one is due. */
	@Schedule(period = 5, unit = ChronoUnit.SECONDS, asynchronous = true)
	public void sendIfDue()
	{
		String key = config.key().trim();
		String who = rsn;
		if (!config.enabled() || key.isEmpty() || keyRejected || who == null)
		{
			return;
		}

		long now = System.currentTimeMillis();
		long sinceFailure = lastFailureAt == 0 ? Long.MAX_VALUE : now - lastFailureAt;
		if (!SendPolicy.shouldSend(queue.hasEventsFor(who), loggedIn, xpChanged, now - lastSendAt, sinceFailure))
		{
			return;
		}
		if (!sending.compareAndSet(false, true))
		{
			return; // the previous request is still going
		}

		List<PluginEvent> events = queue.nextBatch(who);
		boolean withXp = xpChanged && !skillXp.isEmpty();
		if (withXp)
		{
			xpChanged = false;
		}

		Map<String, Object> batch = new LinkedHashMap<>();
		batch.put("rsn", who);
		batch.put("world", world > 0 ? world : null);
		batch.put("skills", withXp ? new HashMap<>(skillXp) : null);
		batch.put("events", events);

		api.sendBatch(config.serverUrl(), key, batch, (code, body) ->
		{
			try
			{
				handleSendResult(code, body, who, events, withXp);
			}
			finally
			{
				sending.set(false);
			}
		});
	}

	private void handleSendResult(int code, String body, String who, List<PluginEvent> events, boolean withXp)
	{
		long now = System.currentTimeMillis();
		if (code == 200)
		{
			lastSendAt = now;
			lastFailureAt = 0;
			Accepted accepted = parseAccepted(body);
			if (accepted.accepted != null && queue.removeIds(new HashSet<>(accepted.accepted)))
			{
				saveQueue();
			}
			if (!announced)
			{
				announced = true;
				chat("Connected as " + who + ".");
			}
			return;
		}

		lastFailureAt = now;
		if (withXp)
		{
			xpChanged = true; // try the XP again next time
		}
		if (code == 401 || code == 409)
		{
			// Wrong key, or a key for another character: waiting won't fix it, so stop until
			// the settings change, and say why.
			keyRejected = true;
			String error = api.errorMessage(body);
			chat(error != null ? error : "Your key wasn't accepted. Make a new one on the site's Group page.");
		}
		else if (code == 400)
		{
			// The site says the batch itself is broken. Resending it would fail forever.
			log.debug("GIM Companion batch rejected: {}", body);
			Set<String> ids = events.stream().map(PluginEvent::getId).collect(Collectors.toSet());
			if (queue.removeIds(ids))
			{
				saveQueue();
			}
		}
		// Anything else (site down, no internet): keep the events and retry in a minute.
	}

	private void checkKey()
	{
		api.whoAmI(config.serverUrl(), config.key().trim(), (code, body) ->
		{
			if (code == 200)
			{
				Me me = parseMe(body);
				announced = true;
				chat("Connected as " + me.rsn + " (" + me.group + ").");
			}
			else if (code == 401)
			{
				keyRejected = true;
				chat("That key wasn't recognised. Copy it again from the site's Group page.");
			}
			else
			{
				chat("Couldn't reach the GIM Companion site. Will keep trying.");
			}
		});
	}

	private void readAllSkills()
	{
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase("Overall"))
			{
				continue; // not a real skill (older RuneLite versions list it)
			}
			int xp = client.getSkillExperience(skill);
			if (xp >= 0)
			{
				skillXp.put(SkillNames.of(skill), xp);
			}
		}
		xpChanged = true;
	}

	private void addEvent(PluginEvent event)
	{
		queue.add(event);
		saveQueue();
	}

	private void loadQueue()
	{
		String saved = configManager.getConfiguration(GimCompanionConfig.GROUP, QUEUE_KEY);
		if (saved == null || saved.isEmpty())
		{
			return;
		}
		try
		{
			queue.replaceAll(gson.fromJson(saved, EVENT_LIST));
		}
		catch (JsonParseException e)
		{
			log.debug("Couldn't read saved GIM Companion events, starting fresh", e);
		}
	}

	private void saveQueue()
	{
		configManager.setConfiguration(GimCompanionConfig.GROUP, QUEUE_KEY, gson.toJson(queue.all(), EVENT_LIST));
	}

	private void chat(String text)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("GIM Companion: ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).runeLiteFormattedMessage(message).build());
	}

	private Accepted parseAccepted(String body)
	{
		try
		{
			Accepted accepted = gson.fromJson(body, Accepted.class);
			return accepted != null ? accepted : new Accepted();
		}
		catch (JsonParseException e)
		{
			return new Accepted();
		}
	}

	private Me parseMe(String body)
	{
		try
		{
			Me me = gson.fromJson(body, Me.class);
			return me != null && me.rsn != null ? me : new Me();
		}
		catch (JsonParseException e)
		{
			return new Me();
		}
	}

	/** The site's answer to a batch. */
	private static class Accepted
	{
		List<String> accepted;
	}

	/** The site's answer to "who is this key for?". */
	private static class Me
	{
		String rsn = "your character";
		String group = "your group";
	}

	@Provides
	GimCompanionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GimCompanionConfig.class);
	}
}

package com.gimcompanion;

/** Spots the game messages that mean you got a pet (pets don't go through the loot tracker). */
public final class PetMessages
{
	private PetMessages()
	{
	}

	private static final String[] PET_MESSAGES = {
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed",
	};

	public static boolean isPetMessage(String message)
	{
		if (message == null)
		{
			return false;
		}
		for (String pet : PET_MESSAGES)
		{
			if (message.contains(pet))
			{
				return true;
			}
		}
		return false;
	}
}

package com.gimcompanion;

import java.util.List;
import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Something that happened in-game, waiting to be sent to the site. Each event gets a random
 * id when it's created, so if a batch is sent twice (say, after a timeout) the site saves it once.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class PluginEvent
{
	static final String LOGIN = "login";
	static final String LOGOUT = "logout";
	static final String DROP = "drop";
	static final String PET = "pet";

	private String id;
	private String type;
	private long at;
	// Which character this happened to. Only events for the character you're logged in as are
	// sent, so events queued on one account never get posted under another.
	private String rsn;
	private String source; // drops: what it dropped from
	private List<DropItem> items; // drops only
	private String message; // pets: the game message

	static PluginEvent login(String rsn, long at)
	{
		return new PluginEvent(newId(), LOGIN, at, rsn, null, null, null);
	}

	static PluginEvent logout(String rsn, long at)
	{
		return new PluginEvent(newId(), LOGOUT, at, rsn, null, null, null);
	}

	static PluginEvent drop(String rsn, long at, String source, List<DropItem> items)
	{
		return new PluginEvent(newId(), DROP, at, rsn, source, items, null);
	}

	static PluginEvent pet(String rsn, long at, String message)
	{
		return new PluginEvent(newId(), PET, at, rsn, null, null, message);
	}

	private static String newId()
	{
		return UUID.randomUUID().toString();
	}
}

package com.gimcompanion;

/**
 * When to send a batch. Checked every few seconds; no game access, so it's easy to test.
 * Keeps requests rare (the site runs on free plans) while making drops and logouts quick.
 */
public final class SendPolicy
{
	static final long XP_EVERY_MS = 60_000;
	static final long HEARTBEAT_EVERY_MS = 5 * 60_000;
	static final long RETRY_AFTER_FAILURE_MS = 60_000;

	private SendPolicy()
	{
	}

	/**
	 * @param hasEvents      logins, logouts, drops or pets are waiting
	 * @param loggedIn       currently in the game
	 * @param xpChanged      XP changed since the last send
	 * @param sinceLastSend  ms since the last successful send
	 * @param sinceFailure   ms since the last failed send (Long.MAX_VALUE if none)
	 */
	public static boolean shouldSend(boolean hasEvents, boolean loggedIn, boolean xpChanged, long sinceLastSend, long sinceFailure)
	{
		if (sinceFailure < RETRY_AFTER_FAILURE_MS)
		{
			return false;
		}
		if (hasEvents)
		{
			return true;
		}
		if (!loggedIn)
		{
			return false;
		}
		return (xpChanged && sinceLastSend >= XP_EVERY_MS) || sinceLastSend >= HEARTBEAT_EVERY_MS;
	}
}

